INSERT INTO `complaints` (`id`, `fecha`, `tipo`, `motivos`, `motivo_otro`, `descripcion`, `created_at`, `updated_at`) VALUES
(7, '2025-10-11', 'sugerencia', '[\"sugerencia_mejora\"]', NULL, 'Implementar herramientas y prácticas que faciliten el flujo de información entre departamentos. Por ejemplo: establecer canales de comunicación claros (como chats internos o plataformas colaborativas), crear reuniones de seguimiento breves y periódicas, definir responsables por área para transmitir información clave, documentar procesos compartidos y fomentar una cultura de colaboración. Esto ayuda a reducir errores, evitar malentendidos y mejorar la coordinación en las tareas diarias.', '2025-10-11 15:27:31', '2025-10-11 15:27:31'),
(8, '2025-12-04', 'peticion', '[\"comunicacion_interna\",\"instalaciones_equipo\"]', NULL, 'fgjghkjgk', '2025-12-04 20:10:02', '2025-12-04 20:10:02'),
(9, '2025-12-03', 'felicitacion', '[\"trato_personal\",\"condiciones_trabajo\"]', NULL, 'fhjkgjkjgkk', '2025-12-04 20:15:29', '2025-12-04 20:15:29');
